"""
This module holds the functionality to fetch (and cache)
the information needed for the bip mirroring.
Since it is expected that the relevant information will not change during a session,
the information is cached in the module global variable "BTS_INFORMATION".
"""
from taf.sbts.oam.coam.admin import AdminConnection
from contextlib import contextmanager
import logging
from . import bip_config
from .tools import python_log


logger = logging.getLogger()


BTS_INFORMATION = {}


def invalidate_cache():
    global BTS_INFORMATION
    BTS_INFORMATION = {}


@contextmanager
def oam_session(gnb_id=0):
    admin = get_oam_session(gnb_id)
    yield admin
    admin.disconnect()


def get_oam_session(gnb_id=0):
    bts_host = bip_config.get_oam_bts_host(gnb_id)
    remote_host = bip_config.get_oam_bts_remote_host(gnb_id)
    return AdminConnection(bts_host=bts_host, remote_host=remote_host)


def get_bts_information(gnb_id=0):
    if gnb_id not in BTS_INFORMATION:
        with oam_session(gnb_id) as admin_connection:
            BTS_INFORMATION[gnb_id] = admin_connection.get_bts_info()
            logger.info("BTS info for gnb_id={}: {}".format(gnb_id, BTS_INFORMATION[gnb_id]))
    return BTS_INFORMATION[gnb_id]


def get_sw_version(gnb_id=0):

    if gnb_id not in bip_config.BIP_CONFIG:
        bip_config.BIP_CONFIG[gnb_id] = {}
    if 'sw_version' in bip_config.BIP_CONFIG[gnb_id]:
        return bip_config.BIP_CONFIG[gnb_id]['sw_version']

    with oam_session(gnb_id) as admin_connection:
        bip_config.BIP_CONFIG[gnb_id]['sw_version'] = admin_connection.get_sw_version()

    return bip_config.BIP_CONFIG[gnb_id]['sw_version']


def get_system_module(gnb_id=0):
    if gnb_id not in bip_config.BIP_CONFIG:
        bip_config.BIP_CONFIG[gnb_id] = {}
    if 'system_module' in bip_config.BIP_CONFIG[gnb_id]:
        return bip_config.BIP_CONFIG[gnb_id]['system_module']
    elif 'gNB_common_unit' in bip_config.BIP_CONFIG[gnb_id]:
        logger.info("gNB_common_unit by configured parameter is deprecated, please use system_module instead")
        return bip_config.BIP_CONFIG[gnb_id]['gNB_common_unit']

    bts_info = get_bts_information(gnb_id)
    sm_product_names = [x['productName'] for x in bts_info['systemModules']]
    try:
        bip_config.BIP_CONFIG[gnb_id]['system_module'] = [x.split(' ')[0] for x in sm_product_names][0]
    except IndexError:
        raise AssertionError('Error in getting system module from bts info!')

    return bip_config.BIP_CONFIG[gnb_id]['system_module']


def get_baseband_modules(gnb_id=0):
    if gnb_id not in bip_config.BIP_CONFIG:
        bip_config.BIP_CONFIG[gnb_id] = {}
    if 'baseband_modules' in bip_config.BIP_CONFIG[gnb_id]:
        return bip_config.BIP_CONFIG[gnb_id]['baseband_modules']
    elif 'gNB_capacity_unit' in bip_config.BIP_CONFIG[gnb_id]:
        logger.info("gNB_capacity_unit by configured parameter is deprecated, please use baseband_module instead")
        return bip_config.BIP_CONFIG[gnb_id]['gNB_capacity_unit']

    bts_info = get_bts_information(gnb_id)
    bb_product_names = [x['productName'] for x in bts_info['basebandModules'] if x.get('productName')]
    bip_config.BIP_CONFIG[gnb_id]['baseband_modules'] = [x.split(' ')[0] for x in bb_product_names]

    return bip_config.BIP_CONFIG[gnb_id]['baseband_modules']


@python_log
def get_vertical_position_from_bbm(gnb_id=0):
    bts_info = get_bts_information(gnb_id)
    with oam_session(gnb_id) as admin_connection:
        bbmod_distname = bts_info['basebandModules'][0]['id']['internal']
        bbmod_params = admin_connection.get_parameters(bbmod_distname)
    return bbmod_params['verticalPosition']


@python_log
def get_bts_info(gnb_id=0):
    bts_info = get_bts_information(gnb_id)

    with oam_session(gnb_id) as admin_connection:
        bbmod_distname = bts_info['basebandModules'][0]['id']['internal']
        bbmod_params = admin_connection.get_parameters(bbmod_distname)

    slot = (bbmod_params['horizontalPosition'] - 1) * 4 + (bbmod_params['verticalPosition'] - 1)
    return slot, bbmod_params['verticalPosition']


@python_log
def get_port_numbers_according_to_slot_id(slot):
    """
    Returns the corresponding mirroring port numbers
    accordint to the input slit ID of baseband module
    """
    slot = str(slot)
    try:
        port1 = {'1': 5, '2': 9, '3': 13, '5': 5, '6': 9, '7': 13}[slot]
        return port1, port1 + 1
    except KeyError:
        logger.error("Slot ID should be 1, 2, 3, 5, 6 or 7 but is {}".format(slot))


@python_log
def get_backplane(vertical, slot, system_module_type):
    """
    Determines the backplane port in form C1B2(6)
    depening on the vertical position, slot type and bb_type
    """
    try:
        bb_id = {'ASIB': '2', 'ASIL': '6'}[system_module_type]
    except KeyError:
        raise AssertionError("System Module type {} not yet supported!".format(system_module_type))

    slot = str(slot)

    mapping = {str(slot): 'C{vertical}B{y}({bb_id})'.format(vertical=vertical, y=y, bb_id=bb_id)
               for slot, y in ((1, 1), (2, 2), (3, 3), (5, 4), (6, 5), (7, 6))}

    try:
        backplane_port = mapping[slot]
    except KeyError:
        logger.error("Error in get_backplane: {} not found in mapping table".format(slot))

    return backplane_port
